function listPage(tasks, query) {
	const fail = (code, message) => ({ status: 400, body: { error: { code, message } } });
	const rawLimit = query.get("limit");
	const limit = rawLimit === null ? 25 : Number(rawLimit);
	if ((rawLimit !== null && !/^\d+$/.test(rawLimit)) || !Number.isInteger(limit) || limit < 1 || limit > 50) {
		return fail("invalid_limit", "limit must be an integer between 1 and 50");
	}
	const status = query.get("status");
	if (status !== null && status !== "open" && status !== "done") {
		return fail("invalid_status", "status must be open or done");
	}
	if (query.has("offset")) return fail("invalid_offset", "offset pagination is not supported");
	let after = null;
	const cursor = query.get("cursor");
	if (cursor !== null) {
		try {
			if (!/^[A-Za-z0-9_-]+$/.test(cursor)) throw new Error();
			const bytes = Buffer.from(cursor, "base64url");
			if (bytes.toString("base64url") !== cursor) throw new Error();
			const token = JSON.parse(bytes.toString("utf8"));
			if (!Array.isArray(token) || token.length !== 3 || token[0] !== 1 ||
				typeof token[1] !== "string" || !/^[0-7][0-9A-HJKMNP-TV-Z]{25}$/.test(token[1]) ||
				token[2] !== status) throw new Error();
			after = token[1];
		} catch {
			return fail("invalid_cursor", "cursor is invalid or does not match the status filter");
		}
	}
	const matching = Array.from(tasks).filter((task) => !task.deleted_at &&
		(status === null || task.status === status) && (after === null || task.id > after));
	matching.sort((a, b) => a.id < b.id ? -1 : a.id > b.id ? 1 : 0);
	const page = matching.slice(0, limit);
	const next_cursor = matching.length > limit
		? Buffer.from(JSON.stringify([1, page[page.length - 1].id, status])).toString("base64url")
		: null;
	return { status: 200, body: { items: page.map((task) => ({ ...task })), next_cursor } };
}
